import{z as r,x as l,o as B,c as o,q as e,j as n,D as a,d as A,s,S as i}from"./chunks/framework.C8m1ZpeB.js";const C=JSON.parse('{"title":"股指期货与贴水","description":"","frontmatter":{"title":"股指期货与贴水","date":"2026-09-18T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/cn-stockindex-basis.md","filePath":"quant/cn-stockindex-basis.md","lastUpdated":1791413859000}'),d={name:"quant/cn-stockindex-basis.md"};function p(c,E,_,D,u,h){const t=l("Mermaid");return B(),o("div",null,[E[2]||(E[2]=e('<h1 id="股指期货与贴水" tabindex="-1">股指期货与贴水 <a class="header-anchor" href="#股指期货与贴水" aria-label="Permalink to &quot;股指期货与贴水&quot;">​</a></h1><div class="epigraph"><p>A 股股指期货的长期贴水不是错误定价，而是对冲需求找不到足够多头对手时给出的出清价；把它当确定收益与把它当确定成本，犯的是同一个错误。</p><footer>—— 据《中国金融期货交易所股指期货交易细则》与对冲拥挤口径整理</footer></div><p><a href="/quant/gm-case-map">上一课</a>把全球市场的制度差异收成对照表，把环境常量显式化：策略等于公式加制度假设，制度变更日按事件日处理。深钻层由此转入中国市场：本课程写在中国把一个策略真正跑起来要过的工具关与生态关。第一件工具是股指期货。<a href="/quant/cn-index-basis-hedge-cost">股指期货基差与对冲成本</a>已把对冲成本记成基差盯市、展期、保证金与冲击四项账单，<a href="/quant/cn-index-fut-basis">股指期货保证金与贴水</a>已写合约要素与贴水形态。本课不重复会计，写每天要回答的实践问题：贴水读数怎么统一、分红怎么剥、展期选哪个月、贴水为什么长期不消失。后课默认已经读完本课。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>成本账单是事后的，实践是事前的。每个收盘后要做三件事：把四个品种的基差换算成可比的年化贴水；把分红预期从贴水里剥出去；为下一次展期挑合约。没有统一口径时，团队对「贴水深」各说各话：有人看当月、有人看季月，有人忘了分红季节，把二季度的日历加深当成对冲拥挤恶化，反过来把拥挤缓和当成选股超额变好。读数错了，后面的展期与预算全错。</p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>读数工程。统一口径：年化贴水取 \\(b_t=-\\ln(F_{t,\\tau}/S_t)/\\tau\\)，\\(F\\) 为期货价、\\(S\\) 为指数点位、\\(\\tau\\) 为剩余期限。IF 与 IH 对应大盘蓝筹，IC 与 IM 对应中证 500 与 1000，四个品种各自成序列，不跨品种混谈。剥分红：二季度前后到期的合约，名义贴水里含预期分红折现，按成分股公告口径估计分红时序，扣掉后得「净贴水」，拥挤读数只看净贴水。展期决策：比较各月合约的年化贴水加冲击成本，取最优而非机械滚近月；贴水环境里远月往往更深，多锁一段深贴水等价于锁定一段对冲成本，但远月流动性差，按参与率分批执行。<span class="marginnote">数字实例：指数 4000 点，某季月合约 3960 点，剩余 3 个月（\\(\\tau=0.25\\) 年），基差 \\(-40\\) 点，年化贴水约 \\(-40/4000/0.25=-4\\%\\)。若这 40 点里有 25 点是二季度分红折现，净贴水只剩约 \\(-1.5\\%\\)——不剥分红，就会把每年 5–7 月的「分红日历」误读成对冲拥挤突然恶化。</span></p>',7)),(B(),n(i,null,{default:a(()=>[s(t,{id:"mermaid-19",class:"mermaid",graph:"flowchart%20TD%0A%20%20FUT%5B%22%E6%9C%9F%E8%B4%A7%E4%BB%B7%E6%A0%BC%22%5D%20--%3E%20ANN%5B%22%E5%B9%B4%E5%8C%96%E8%B4%B4%E6%B0%B4%22%5D%0A%20%20SPOT%5B%22%E6%8C%87%E6%95%B0%E7%82%B9%E4%BD%8D%22%5D%20--%3E%20ANN%0A%20%20ANN%20--%3E%20NET%5B%22%E5%87%80%E8%B4%B4%E6%B0%B4%22%5D%0A%20%20DIV%5B%22%E9%A2%84%E6%9C%9F%E5%88%86%E7%BA%A2%E6%8A%98%E7%8E%B0%22%5D%20--%3E%20NET%0A%20%20NET%20--%3E%20MON%5B%22%E6%8B%A5%E6%8C%A4%E8%AF%BB%E6%95%B0%22%5D%0A%20%20CURVE%5B%22%E5%90%84%E6%9C%88%E5%90%88%E7%BA%A6%E5%B9%B4%E5%8C%96%E8%B4%B4%E6%B0%B4%22%5D%20--%3E%20ROLL%5B%22%E5%B1%95%E6%9C%9F%E5%90%88%E7%BA%A6%E9%80%89%E6%8B%A9%22%5D%0A%20%20IMP%5B%22%E5%86%B2%E5%87%BB%E6%88%90%E6%9C%AC%22%5D%20--%3E%20ROLL%0A"})]),fallback:a(()=>[...E[0]||(E[0]=[A(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=e('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>贴水为什么长期存在。对冲需求天然压在期货卖出侧：中性产品的空头腿、发行雪球的券商对冲盘（高抛低吸的对冲行为与成本结构见<a href="/quant/snowball-pricing">雪球结构与定价</a>与<a href="/quant/snowball-dealer-hedging">对冲商的障碍期权堆积与 gamma</a>）都在卖期货。反向套利本该把贴水拉回来，但它要买期货、融券卖出整个现货篮子，被 T+1、涨跌停与券源掐住（<a href="/quant/cn-tplus1">T+1 与回转交易约束</a>），收敛通道窄而慢，贴水因此可以常年不消失。均衡位置由多头承接决定：吃贴水的多头替代资金进得越多，贴水越浅；贴水浅则对冲便宜、中性规模回升、卖压再把贴水买深，负反馈把贴水钉在一个带宽里。所以贴水是状态变量：读它的水平与变化率，比猜它的方向有用。<span class="marginnote">术语翻译：「贴水」就是期货比指数现货便宜的那截价差。直觉上它是空头腿付的保险费：中性产品必须卖期货把指数风险转移出去，卖的人多、愿意接的人少，价格就得打到让多头觉得「接了划算」为止——长期贴水就是这份风险转移服务的市价，不是免费午餐也不是错误定价。</span></p>',2)),(B(),n(i,null,{default:a(()=>[s(t,{id:"mermaid-26",class:"mermaid",graph:"flowchart%20LR%0A%20%20HEDGE%5B%22%E4%B8%AD%E6%80%A7%E4%BA%A7%E5%93%81%E4%B8%8E%E9%9B%AA%E7%90%83%E5%AF%B9%E5%86%B2%E7%9A%84%E5%8D%96%E6%9C%9F%E9%9C%80%E6%B1%82%22%5D%20--%3E%20DEEP%5B%22%E6%9C%9F%E8%B4%A7%E5%8D%96%E5%8E%8B%20%E8%B4%B4%E6%B0%B4%E5%8A%A0%E6%B7%B1%22%5D%0A%20%20DEEP%20--%3E%20YIELD%5B%22%E5%A4%9A%E5%A4%B4%E6%9B%BF%E4%BB%A3%E7%9A%84%E5%90%83%E8%B4%B4%E6%B0%B4%E6%94%B6%E7%9B%8A%E5%8F%98%E5%8E%9A%22%5D%0A%20%20YIELD%20--%3E%20IN%5B%22%E6%9B%BF%E4%BB%A3%E8%B5%84%E9%87%91%E8%BF%9B%E5%9C%BA%E6%89%BF%E6%8E%A5%22%5D%0A%20%20IN%20--%3E%20SHALLOW%5B%22%E8%B4%B4%E6%B0%B4%E6%94%B6%E6%95%9B%E5%8F%98%E6%B5%85%22%5D%0A%20%20SHALLOW%20--%3E%20CHEAP%5B%22%E5%AF%B9%E5%86%B2%E5%8F%98%E4%BE%BF%E5%AE%9C%22%5D%0A%20%20CHEAP%20--%3E%20SCALE%5B%22%E4%B8%AD%E6%80%A7%E8%A7%84%E6%A8%A1%E5%9B%9E%E5%8D%87%20%E5%8D%96%E5%8E%8B%E5%86%8D%E5%A2%9E%22%5D%0A%20%20SCALE%20--%3E%20DEEP%0A%20%20T1%5B%22T%2B1%20%E6%B6%A8%E8%B7%8C%E5%81%9C%20%E5%88%B8%E6%BA%90%E7%BA%A6%E6%9D%9F%22%5D%20-.-%3E%7C%22%E6%8E%90%E7%AA%84%E6%94%B6%E6%95%9B%E9%80%9A%E9%81%93%22%7C%20ARB%5B%22%E5%8F%8D%E5%90%91%E5%A5%97%E5%88%A9%22%5D%0A"})]),fallback:a(()=>[...E[1]||(E[1]=[A(" Loading... ",-1)])]),_:1})),E[4]||(E[4]=e('<p><span class="marginnote">年化贴水要除以剩余期限，临到期时基差一点抖动都会被放大成年化读数的剧烈跳动；到期前两周应改看基差绝对值与收敛斜率，不要再看年化。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不给贴水预测模型，也不把吃贴水写成无风险：多头替代承担完整的指数贝塔与保证金盯市的现金流风险。限仓、保证金比例与套保额度是政策变量，读数体系必须能容纳制度跳变。用 IC 对冲中证 800 组合这类跨品种对冲留下市值残差，属另一课的问题。交割结算价的可能操纵不在讨论范围。<span class="marginnote">常见误区：初学者容易把「年化贴水 10%」当成每年白拿的票息。实际上多头替代腿全额承受指数涨跌——指数跌 25% 时你照样亏掉 25% 再赚回 10% 贴水；波动放大时保证金还要追加现金。吃贴水是「贴水 + 贝塔 + 保证金现金流」的组合，不是固定收益。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>贴水读数统一成年化口径、四品种分列、剥除分红后再当拥挤读数。</li><li>展期比的是年化贴水加冲击，机械滚近月在深贴水期多付成本。</li><li>贴水长期存在，机制是对冲需求单边压价、反向套利通道被做空约束掐窄。</li><li>贴水是状态变量：水平与变化率进监控，方向不进预测。</li><li>出处：中金所股指期货合约与结算细则口径；成本记账见<a href="/quant/cn-index-basis-hedge-cost">股指期货基差与对冲成本</a>。</li></ul>',5))])}const f=r(d,[["render",p]]);export{C as __pageData,f as default};
